        [SerializeField]
        GameObject artifactChoosingDialogObj = null!;
        [SerializeField]
        ArtifactChoosingDialog artifactChoosingDialog = null!;
        [SerializeField]
        MovingBlueprintList movingBlueprints = null!;
        [SerializeField]
        BlueprintChoosePanel blueprintChoosePanel = null!;
        [SerializeField]
        CommandBlockChoosePanel commandBlockChoosePanel = null!;
        [SerializeField]
